def find_First_Missing(array, start=0, end=None):
    if end is None:
        end = len(array) - 1
    if start > end:
        return array[0] if start == 0 else start
    if array[start] != start:
        return start
    mid = (start + end) // 2
    if array[mid] == mid:
        return find_First_Missing(array, mid + 1, end)
    return find_First_Missing(array, start, mid)

